  const cards = Array.from(document.querySelectorAll('article[data-test="property-card"], .list-card, [data-test="property-card-link"]'));
  const links = Array.from(document.querySelectorAll('a[data-test="property-card-link"]')).map(a => ({
    href: a.href,
    text: a.innerText,
    address: a.querySelector('address')?.innerText || a.innerText
  }));

  // Also general property card extraction
  const cardData = Array.from(document.querySelectorAll('article')).map(art => {
    const link = art.querySelector('a[data-test="property-card-link"]')?.href || art.querySelector('a')?.href;
    const address = art.querySelector('address')?.innerText;
    const price = art.querySelector('[data-test="property-card-price"]')?.innerText;
    const details = art.querySelector('ul')?.innerText;
    return { link, address, price, details };
  }).filter(c => c.link && c.link.includes('homedetails'));

  return {
    linksCount: links.length,
    links: links.slice(0, 10),
    cardDataCount: cardData.length,
    cardData: cardData.slice(0, 10)
  };
});
