for (const tabId of zillowTabs) {
  const data = await browserjs(tabId, () => {
    const price = document.querySelector('[data-testid="price"], span[data-test="property-card-price"]')?.innerText || 
                  Array.from(document.querySelectorAll('span, h2, h3')).find(el => el.innerText.startsWith('$') && el.innerText.length < 15)?.innerText;
    const address = document.querySelector('h1')?.innerText || document.title;
    return {
      tabId,
      url: window.location.href,
      title: document.title,
      price: price || document.body.innerText.match(/\$[0-9,]+/)?.[0],
      address: address
    };
  });
  results.push(data);
}

console.log(JSON.stringify(results, null, 2));

